import { readFile, writeFile, mkdir } from 'node:fs/promises'
import { join, resolve } from 'node:path'
import ts from 'typescript'

/**
 * Compile the Web question lifecycle for the App carrier without forking its policy.
 *
 * The result is the only JavaScript copy of `slots.ts`; callers write it to the
 * carrier where a plain-Node consumer loads it. `apps/android/runtime` is that
 * consumer both on the device (through the staged runtime bundle) and on the PC
 * remote host (which loads the workspace package directly), so the checked-in
 * copy in the package is regenerated by this tool and must not be edited by hand.
 * @returns The generated module text, including the generated-file header.
 */
export async function compileQuestionCarrier() {
  const root = resolve(import.meta.dirname, '../../..')
  const source = join(root, 'packages/client/ui-user-questions/src/client/contract/slots.ts')
  const compiled = ts.transpileModule(await readFile(source, 'utf8'), {
    fileName: source,
    compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ESNext },
    reportDiagnostics: true,
  })
  const errors = compiled.diagnostics?.filter(item => item.category === ts.DiagnosticCategory.Error) ?? []
  if (errors.length) throw new Error(ts.formatDiagnosticsWithColorAndContext(errors, {
    getCanonicalFileName: file => file, getCurrentDirectory: () => root, getNewLine: () => '\n',
  }))
  return '// Generated from packages/client/ui-user-questions/src/client/contract/slots.ts.\n'
    + '// Regenerate with: node apps/android/tool/stage-question-carrier.mjs --write\n'
    + compiled.outputText
}

/**
 * Write the generated module into a carrier destination.
 * @param destination - directory that receives `question-carrier.mjs`.
 * @returns The written path.
 */
export async function stageQuestionCarrier(destination) {
  await mkdir(destination, { recursive: true })
  const path = join(destination, 'question-carrier.mjs')
  await writeFile(path, await compileQuestionCarrier())
  return path
}

/** The checked-in copy the PC remote host loads from the workspace package. */
const workspaceCarrier = resolve(import.meta.dirname, '../runtime')

if (process.argv[1] && resolve(process.argv[1]) === resolve(import.meta.filename)) {
  if (process.argv.includes('--write')) {
    await stageQuestionCarrier(workspaceCarrier)
    console.log(`Wrote ${join(workspaceCarrier, 'question-carrier.mjs')}`)
  } else {
    await stageQuestionCarrier(resolve(import.meta.dirname, '../../../.cache/android/runtime-bundle/node_modules/@minnnng/dsh-android-runtime'))
  }
}
